functionImplementations.EntityInfo:
// Unable to retrieve the property of Entity in the normal way because the API only applies to generic dimensions
// Returns:
//  Entity ID in position 1 i.e. [0] e.g. [PPP_Entity].[H1].&[ND10]
//  Entity ID (simple) in position 2 i.e. [1] e.g. ND10
//  Entity classification in position 2 i.e. [2] e.g. "REFINERIE" or "UPSTREAM"

var resultList = ArrayUtils.create(Type.string);
var tableRS = Table_Helper.getDataSource().getResultSet();

resultList[0] = tableRS[0]["PPP_Entity"].id;
resultList[1] = BusRules.simpleMemberID(resultList[0]);
resultList[2] = tableRS[0]["PPP_Entity"].properties["PPP_Entity.Classification"];

Classification = resultList[2];

console.log(resultList);
return (resultList);

functionImplementations.onEntityChange:
// Set the correct work program layout depending on the entities classification.


// Note: The user can select more than one entity (current configuration) so the layout is determined
// by the first entity in the returned list

// BusRules.EntityInfo must be executed to set the variable CLASSIFICATION. The return value can be
// used or the variable for ease of use.

// If the helper table is refreshed it triggers an entity change which is the only way to detect if the story filter changed the entity.
// However, the table is also refereshed after publishing data etc and so an entity change event is triggered often for the wrong reasons.
// To catch this an entity change is checked against a variable and only if the entity actually changed will the rest of this function execute.

if (CurrentEntity === BusRules.EntityInfo()[0]) {
	return;
} else {
	CurrentEntity = BusRules.EntityInfo()[0];
}


// An additional setting for the JV node identified as the CPY of the JV's
if (BusRules.EntityInfo()[2] === "UPSTREAM_CPY") {
		Application.showBusyIndicator("Setting up upstream company variant layout");

		Panel_WP_Generic.setVisible(false);

		Dropdown_11.setSelectedKey("Value 1");
		Dropdown_12.setSelectedKey("Value 1");
		BusRules.setDropdowns(Dropdown_11,"SET25");
		BusRules.setDropdowns(Dropdown_12,"SET30");

		Panel_UStream_WPCpy.setVisible(true);

		Application.hideBusyIndicator();	

	} else {

		Application.showBusyIndicator("Setting up Objectives layouts");

		Panel_UStream_WPCpy.setVisible(false);

		Switch_1.setVisible(false);
		Text_12.setVisible(false);

		DataUploadStarter_Obj.setVisible(true);
		Panel_WP_Generic.setVisible(true);

		var objList = Objectives.availableList();
		Table_Obj.getDataSource().setDimensionFilter("Objectives", objList);
		Table_Strat.getDataSource().setDimensionFilter("Objectives", objList);
		Table_WPAssign.getDataSource().setDimensionFilter("Objectives", objList);	


