functionImplementations.rowCountValidations:
// Checking the validation of objectives which must be between 3 and 6

Application.showBusyIndicator("Checking row counts");

var rowCount = Table_Obj.getRowCount();
console.log(rowCount);

if (rowCount >= 6) 
{
    Table_Obj.setContextMenuVisible(false);
    Panel_6Rows.setVisible(true);
    Panel_3to6.setVisible(false);
    Panel_Min3.setVisible(false);
};

if (rowCount >= 3 && rowCount < 6)
{
    Table_Obj.setContextMenuVisible(true);
    Panel_3to6.setVisible(true);
    Panel_6Rows.setVisible(false);
    Panel_Min3.setVisible(false);
};

if (rowCount < 3)
{
    Table_Obj.setContextMenuVisible(true);
    Panel_Min3.setVisible(true);
    Panel_3to6.setVisible(false);
    Panel_6Rows.setVisible(false);
};

// Checking the validation of strategies which must be less than 3 per objective
// The validation table excludes the details of the strategies so the measure
// which is set to 1 for each strategy sums up the number of strategies. If more
// than 3 indicates a violation and activates the popup button to then see which objective is at fault
var rsValid = Table_Validation.getDataSource().getResultSet();
console.log("Validation table result set:");
console.log(rsValid);
Button_38.setVisible(false);

for (var k = 0; k < rsValid.length; k++) {
	if (rsValid[k]["@MeasureDimension"].rawValue > "3") {
		Button_38.setVisible(true);
	};
};

Application.hideBusyIndicator();

functionImplementations.availableList:
// Fetch the list of available objectives which is identified in the ADMIN story

Table_Avail.getDataSource().refreshData();
var rsAvail = Table_Avail.getDataSource().getResultSet();

console.log("The list in the Availability table:");
console.log(rsAvail);

var objList = ArrayUtils.create(Type.string);

for (var i = 0; i < rsAvail.length; i++) {
	if (rsAvail[i]["Objectives"] !== undefined) {
		var obj = rsAvail[i]["Objectives"].id;
		if (objList.indexOf(obj) === -1) {
    		objList.push(rsAvail[i]["Objectives"].id);
		};
	};
};

console.log("The extracted list of available objectives:");
console.log(objList);
return(objList);

